// Native values follow pret/pokefirered/include/constants/weather.h.
// Drought (12) is deliberately excluded: its original overworld effect is broken.
export const MAP_WEATHER=[[0,'Clear / no weather'],[2,'Sunny'],[3,'Rain'],[4,'Snow'],[5,'Thunderstorm'],[6,'Low fog'],[8,'Sandstorm'],[9,'Drifting fog'],[11,'Shade'],[13,'Heavy rain']];
export function validateEnvironment(map){const e=map.environment;if(e!==undefined&&(!e||typeof e!=='object'||e.weather!==undefined&&!MAP_WEATHER.some(([id])=>id===e.weather)||e.preview!==undefined&&typeof e.preview!=='boolean'))throw Error('Choose a supported map weather.');}
export function weatherFields(map,esc){const value=map?.environment?.weather??'',original=MAP_WEATHER.find(([id])=>id===map?.rom?.weather)?.[1]||'original';return `<label>Map weather<select id="mapWeather"><option value="" ${value===''?'selected':''}>${map?.rom?'Keep ROM weather · '+esc(original):'Default / clear'}</option>${MAP_WEATHER.map(([id,name])=>`<option value="${id}" ${value===id?'selected':''}>${name}</option>`).join('')}</select></label><label class="check"><input id="mapWeatherPreview" type="checkbox" ${map?.environment?.preview!==false?'checked':''}> Show weather preview on the editor map</label><p class="hint-line">Weather is written to the native map header. The editor shows a still preview; the game runs its own effects. Puddles are separate walkable artwork under Ready-made → Ground details.</p>`;}
export function drawWeatherPreview(c,map,view={x:0,y:0,w:map.width*16,h:map.height*16}){if(map.environment?.preview===false)return;const id=map.environment?.weather??map.rom?.weather;if(!id||id===2)return;const w=map.width*16,h=map.height*16,x0=Math.max(0,view.x-40),y0=Math.max(0,view.y-40),x1=Math.min(w,view.x+view.w+40),y1=Math.min(h,view.y+view.h+40);c.save();c.beginPath();c.rect(0,0,w,h);c.clip();
 if([3,5,13,8].includes(id)){c.fillStyle=id===8?'#bc9d4f24':'#20406330';c.fillRect(0,0,w,h);c.strokeStyle=id===8?'#ddc78a99':'#bad6e577';c.lineWidth=1;for(let y=Math.floor(y0/23)*23;y<y1;y+=23)for(let x=Math.floor(x0/29)*29;x<x1;x+=29){const xx=x+(y*7%29);c.beginPath();c.moveTo(xx,y);c.lineTo(xx-3,y+(id===13?13:7));c.stroke();}}
 else if(id===4){c.fillStyle='#dfeeff20';c.fillRect(0,0,w,h);c.fillStyle='#f7fcffcc';for(let y=Math.floor(y0/27)*27+7;y<y1;y+=27)for(let x=Math.floor(x0/31)*31+3;x<x1;x+=31)c.fillRect(x+(y%11),y,2,2);}
 else if(id===6||id===9){c.fillStyle='#e3e9e85c';c.fillRect(0,0,w,h);c.fillStyle='#f7f9f733';for(let y=Math.floor(y0/38)*38;y<y1;y+=38)c.fillRect(0,y,w,15);}
 else if(id===11){c.fillStyle='#151f4438';c.fillRect(0,0,w,h);}c.restore();}
export function installMapWeather(output,map,native){validateEnvironment(map);const value=map.environment?.weather;if(value===undefined)return false;if(output.bytes[native.address+22]===value)return false;output.write(native.address+22,Uint8Array.of(value));return true;}
